router = APIRouter()


logger = structlog.get_logger(__name__)


@lru_cache(maxsize=1)
def get_token_broker() -> RealtimeTokenBroker:
    return OpenAIRealtimeTokenBroker(get_settings())


@lru_cache(maxsize=1)
def get_cala_client() -> CalaClient:
    """One client, one ledger, one cache, for the life of the process. The `lru_cache` is what
    makes "one Cala call site" true at runtime rather than only by convention."""
    return CalaClient(get_settings())


@lru_cache(maxsize=1)
def get_discovery_service() -> DiscoveryService:
    """One process-wide service so its query cache is shared across sessions."""
    return build_discovery_service(get_settings())


@lru_cache(maxsize=1)
def get_image_fetcher() -> ImageFetcher:
    settings = get_settings()
    return ImageFetcher(
        allowlist=settings.image_host_allowlist,
        user_agent=settings.image_fetch_user_agent,
        max_bytes=settings.image_fetch_max_bytes,
        connect_timeout=settings.image_fetch_connect_timeout,
        total_timeout=settings.image_fetch_total_timeout,
    )


@router.get("/health")
async def health(settings: Annotated[Settings, Depends(get_settings)]) -> HealthResponse:
    return HealthResponse(
        status="ok",
        service="glia-api",
        mode=settings.demo_mode,
        realtime="configured" if settings.openai_api_key else "unconfigured",
        distiller=(
            "fixture"
            if settings.demo_mode == "fixture"
            else "configured"
            if settings.pioneer_api_key
            else "unconfigured"
        ),
        # The candidate pipeline does not exist yet, so no configuration can make this true.
        # It becomes a real capability check when discovery lands; until then the client has to
        # be told plainly that no image can arrive, rather than being allowed to ask for one.
        image_discovery=False,
    )


@router.post("/api/realtime-token", response_model=RealtimeTokenResponse)
async def realtime_token(
    payload: RealtimeTokenRequest,
    request: Request,
    broker: Annotated[RealtimeTokenBroker, Depends(get_token_broker)],
) -> RealtimeTokenResponse | JSONResponse:
    correlation_id = request.headers.get("X-Request-ID", str(uuid4()))
    try:
        return await broker.mint(payload.client_id, payload.languages)
    except TokenBrokerUnavailable:
        return _problem(
            status=503,
            code="realtime_not_configured",
            title="Realtime transcription is not configured",
            detail="The server is missing its OpenAI API key.",
            correlation_id=correlation_id,
        )
    except TokenMintFailed:
        return _problem(
            status=502,
            code="realtime_upstream_failed",
            title="Realtime transcription is temporarily unavailable",
            detail="The server could not mint a short-lived transcription credential.",
            correlation_id=correlation_id,
        )


@router.get("/v1/ledger", response_model=LedgerSnapshot)
async def ledger(
    client: Annotated[CalaClient, Depends(get_cala_client)],
) -> LedgerSnapshot:
    """Credits spent this process. In-process, so it resets with the API — that is a known
    limitation of today's counter, not a claim about the monthly pool."""
    return client.snapshot()

export type ConnectionState = 'idle' | 'connecting' | 'connected' | 'error'

export interface VisualIntent {
  subject: string
  moods: string[]
  styles: string[]
  palette: string[]
  composition: string
  medium: string
  era: string
}

export type IntentSource = 'fixture' | 'local' | 'pioneer'
export type IntentChangeReason = 'initial' | 'subject' | 'medium' | 'era' | 'visual_attributes'

export interface TranscriptAccepted {
  type: 'transcript.accepted'
  item_id: string
  transcript: string
  complete: boolean
}

export interface IntentUpdated {
  type: 'intent.updated'
  revision: number
  transcript: string
  intent: VisualIntent
  stable: boolean
  source: IntentSource
  should_discover: boolean
  change_reasons: IntentChangeReason[]
}

export type ServerMessage =
  | {
      type: 'session.ready'
      session_id: string
      debounce_ms: number
      heartbeat_interval_ms: number
    }
  | TranscriptAccepted
  | IntentUpdated
  | { type: 'pong'; event_id: string }
  | { type: 'error'; code: string; detail: string; recoverable: boolean }

export type ClientMessage =
  | { type: 'transcript.delta'; event_id: string; item_id: string; delta: string }
  | { type: 'transcript.completed'; event_id: string; item_id: string; transcript: string }
  | { type: 'ping'; event_id: string }

type UnknownRecord = Record<string, unknown>

function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function hasString(value: UnknownRecord, key: string): boolean {
  return typeof value[key] === 'string'
}

function hasNumber(value: UnknownRecord, key: string): boolean {
  return typeof value[key] === 'number'
}

function hasBoolean(value: UnknownRecord, key: string): boolean {
  return typeof value[key] === 'boolean'
}

function hasStringArray(value: UnknownRecord, key: string): boolean {
  const candidate = value[key]
  return Array.isArray(candidate) && candidate.every((item) => typeof item === 'string')
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw) as unknown
  } catch {
    return null
  }
}

export function parseRealtimeTokenResponse(value: unknown): {
  value: string
  expires_at: number
  model: string
} | null {
  if (
    !isRecord(value) ||
    !hasString(value, 'value') ||
    !hasNumber(value, 'expires_at') ||
    !hasString(value, 'model')
  ) {
    return null
  }
  return {
    value: value.value as string,
    expires_at: value.expires_at as number,
    model: value.model as string,
  }
}

function parseVisualIntent(value: unknown): VisualIntent | null {
  if (!isRecord(value) || !hasString(value, 'subject')) {
    return null
  }
  if (
    !hasStringArray(value, 'moods') ||
    !hasStringArray(value, 'styles') ||
    !hasStringArray(value, 'palette') ||
    !hasString(value, 'composition') ||
    !hasString(value, 'medium') ||
    !hasString(value, 'era')
  ) {
    return null
  }
  return {
    subject: value.subject as string,
    moods: value.moods as string[],
    styles: value.styles as string[],
    palette: value.palette as string[],
    composition: value.composition as string,
    medium: value.medium as string,
    era: value.era as string,
  }
}

const intentSources = new Set<IntentSource>(['fixture', 'local', 'pioneer'])
const intentChangeReasons = new Set<IntentChangeReason>([
  'initial',
  'subject',
  'medium',
  'era',
  'visual_attributes',
])

export function parseServerMessage(raw: string): ServerMessage | null {
  const value = parseJson(raw)
  if (!isRecord(value) || !hasString(value, 'type')) {
    return null
  }
  switch (value.type) {
    case 'session.ready':
      if (
        hasString(value, 'session_id') &&
        hasNumber(value, 'debounce_ms') &&
        hasNumber(value, 'heartbeat_interval_ms')
      ) {
        return value as unknown as ServerMessage
      }
      return null
    case 'transcript.accepted':
      if (
        hasString(value, 'item_id') &&
        hasString(value, 'transcript') &&
        hasBoolean(value, 'complete')
      ) {
        return value as unknown as TranscriptAccepted
      }
      return null
    case 'intent.updated': {
      const intent = parseVisualIntent(value.intent)
      if (
        intent &&
        hasNumber(value, 'revision') &&
        hasString(value, 'transcript') &&
        hasBoolean(value, 'stable') &&
        hasString(value, 'source') &&
        intentSources.has(value.source as IntentSource) &&
        hasBoolean(value, 'should_discover') &&
        hasStringArray(value, 'change_reasons') &&
        (value.change_reasons as string[]).every((reason) =>
          intentChangeReasons.has(reason as IntentChangeReason),
        )
      ) {
        return {
          type: 'intent.updated',
          revision: value.revision as number,
          transcript: value.transcript as string,
          intent,
          stable: value.stable as boolean,
          source: value.source as IntentSource,
          should_discover: value.should_discover as boolean,
          change_reasons: value.change_reasons as IntentChangeReason[],
        }
      }
      return null
    }
    case 'pong':
      return hasString(value, 'event_id') ? (value as unknown as ServerMessage) : null
    case 'error':
      if (
        hasString(value, 'code') &&
        hasString(value, 'detail') &&
        hasBoolean(value, 'recoverable')
      ) {
        return value as unknown as ServerMessage
      }
      return null
    default:
      return null
  }
}
