      const m = JSON.parse(e.data);
      if (m.type === 'session.ready') {
        ws.send(JSON.stringify({ type: 'transcript.completed', event_id: 'e1', item_id: 'i1',
          transcript: 'I want a brutalist observatory at dusk' }));
      }
      if (m.type === 'candidates.batch') out.push(...m.candidates);
    };
    setTimeout(() => { ws.close(); resolve(out); }, 4000);
  });
  return { outputDefault: s.output, storageKey: Object.keys(localStorage), got: candidates.length,
           sample: candidates[0] };
})()

(async () => {
  const { useSessionStore } = await import('/src/stores/session.ts');
  const { useSettings } = await import('/src/stores/settings.ts');
  window.__glia = { useSessionStore, useSettings };
  // Start a Cumulative Layout Shift observer BEFORE any candidate lands.
  window.__cls = 0;
  new PerformanceObserver((list) => {
    for (const e of list.getEntries()) if (!e.hadRecentInput) window.__cls += e.value;
  }).observe({ type: 'layout-shift', buffered: true });
  return {
    outputDefault: useSettings.getState().output,
    persistedKeys: Object.keys(localStorage),
  };
})()

(async () => {
  const { useSessionStore } = window.__glia;
  const store = useSessionStore.getState();
  store.startSession();
  store.setTranscriptState('I want a brutalist observatory at dusk',
    [{ itemId: 'i1', text: 'I want a brutalist observatory at dusk', complete: true }]);

  const t0 = performance.now();
  const timings = [];
  await new Promise((resolve) => {
    const ws = new WebSocket('ws://localhost:8010/ws');
    ws.onmessage = (e) => {
      const m = JSON.parse(e.data);
      if (m.type === 'session.ready') {
        ws.send(JSON.stringify({ type: 'transcript.completed', event_id: 'e1', item_id: 'i1',
          transcript: 'I want a brutalist observatory at dusk' }));
      }
      if (m.type === 'candidates.batch') {
        timings.push({ n: m.candidates.length, at: +(performance.now() - t0).toFixed(0) });
        // Feed the REAL store action the app's own socket handler calls.
        useSessionStore.getState().appendCandidates(m.candidates);
      }
    };
    setTimeout(() => { ws.close(); resolve(); }, 5000);
  });
  const st = useSessionStore.getState();
  return { waves: timings, inStore: st.candidates.length, subject: st.candidateSubject };
})()

