  await new Promise(r => setTimeout(r, 1500));            // let every image decode

  const during = window.__shifts.slice(shiftsBeforeGrid);
  return {
    beforeGrid: { count: shiftsBeforeGrid, cls: +totalBeforeGrid.toFixed(4),
                  what: window.__shifts.slice(0,4).map(x=>x.src) },
    whileGridFilled: { count: during.length, cls: +during.reduce((a,b)=>a+b.v,0).toFixed(4),
                       entries: during.slice(0,5) },
    tiles: document.querySelectorAll('.candidate-tile').length,
  };
})()

(async () => {
  // Block /v1/discover entirely, exactly as an unreachable Cala would look to the browser.
  const realFetch = window.fetch;
  window.fetch = (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (url.includes('/v1/discover')) return Promise.reject(new TypeError('Failed to fetch'));
    return realFetch(input, init);
  };

  const { useSessionStore } = window.__glia;
  const s = useSessionStore.getState();
  s.setSessionId('sess-blocked');
  // shouldDiscover=true is what actually fires useDiscovery against the dead endpoint.
  s.setIntent({ subject: 'brutalist observatory at dusk', moods: [], styles: [], palette: [],
                composition: '', medium: '', era: '' },
              'I want a brutalist observatory at dusk', true);
  await new Promise(r => setTimeout(r, 2500));

  const pane = document.querySelector('[aria-label="Workpane"]');
  return {
    workpanePresent: Boolean(pane),
    tilesStillOnScreen: document.querySelectorAll('.candidate-tile').length,
    gridPresent: Boolean(document.querySelector('.candidate-grid')),
    paneText: pane ? pane.innerText.split('\n').filter(Boolean).slice(-3) : null,
    clsTotal: window.__shifts.reduce((a,b)=>a+b.v, 0),
  };
})()

(async () => {
  // /v1/discover is still blocked from the previous step. Now do it in real order:
  // intent settles (clears the grid) → lanes ship over the WebSocket → grid refills.
  const { useSessionStore } = window.__glia;
  useSessionStore.getState().setIntent(
    { subject: 'observatory dusk', moods: [], styles: [], palette: [],
      composition: '', medium: '', era: '' },
    'I want a brutalist observatory at dusk', true);

  await new Promise((res)=>{
    const ws = new WebSocket('ws://localhost:8010/ws');
    ws.onmessage = (e) => { const m = JSON.parse(e.data);
      if (m.type==='session.ready') ws.send(JSON.stringify({type:'transcript.completed',
        event_id:'e1', item_id:'i1', transcript:'I want a brutalist observatory at dusk'}));
      if (m.type==='candidates.batch') useSessionStore.getState().appendCandidates(m.candidates); };
    setTimeout(()=>{ws.close(); res()}, 6000);
  });
  await new Promise(r => setTimeout(r, 1200));

  const pane = document.querySelector('[aria-label="Workpane"]');
  return {
    calaBlocked: true,
    workpanePresent: Boolean(pane),
    gridPresent: Boolean(document.querySelector('.candidate-grid')),
    tiles: document.querySelectorAll('.candidate-tile').length,
    calaNoteShown: pane ? /Source lookup failed/.test(pane.innerText) : null,
    clsTotal: +window.__shifts.reduce((a,b)=>a+b.v,0).toFixed(4),
  };
})()

(async () => {
  // The strictest form: 'both' mode, Cala still blocked. The failure must show as a small
  // secondary note UNDER the grid, never as the whole pane.
  const { useSettings } = await import('/src/stores/settings.ts');
  useSettings.getState().setOutput('both');
  await new Promise(r => setTimeout(r, 2500));

  const pane = document.querySelector('[aria-label="Workpane"]');
  const grid = document.querySelector('.candidate-grid');
  const notes = [...pane.querySelectorAll('.discovery-item')].map(n => n.innerText.trim());
  return {
    output: useSettings.getState().output,
    workpanePresent: Boolean(pane),
    gridPresent: Boolean(grid),
    tiles: document.querySelectorAll('.candidate-tile').length,
    calaFailureNote: notes,
    gridComesFirst: grid && notes.length
      ? grid.getBoundingClientRect().top < pane.querySelector('.discovery-item').getBoundingClientRect().top
      : null,
    clsTotal: +window.__shifts.reduce((a,b)=>a+b.v,0).toFixed(4),
  };
})()

